import math
class Solution:
    def minOperations(self, nums):
        best = float('inf')
        for t in range(2, max(nums) + 1):
            total = 0
            ok = True
            for v in nums:
                if v == t:
                    continue
                if v % t == 0 or t % v == 0:
                    total += 1
                elif math.gcd(v, t) > 1:
                    total += 2
                else:
                    ok = False
                    break
            if ok:
                best = min(best, total)
        return best if best != float('inf') else -1

