        cnt = Counter(nums)
        vals = list(cnt)
        cands = set()
        for v in vals:
            cands.add(v)
            i = 1
            while i * i <= v:
                if v % i == 0:
                    if i > 1:
                        cands.add(i)
                    if v // i > 1:
                        cands.add(v // i)
                i += 1
        best = float('inf')
        for t in cands:
            total = 0
            ok = True
            for v in vals:
                c = cnt[v]
                if v == t:
                    continue
                if v % t == 0 or t % v == 0:
                    total += c
                elif gcd(v, t) > 1:
                    total += 2 * c
                else:
                    ok = False
                    break
                if total >= best:
                    ok = False
                    break
            if ok:
                best = min(best, total)
